import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let s = "a" + "b"
    let m = conc.Mutex(0)
    var n: Int64 = 0
    n = m.update(|v| v + s.byteLength())
    io.println("${n}")
    return Ok(())
}
